import sqlite3
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('experiment-tracker')

@mcp.tool()
def get_run_metric(run_id: str, metric: str) -> dict:
    db = sqlite3.connect('/var/lib/tracker/tracker.db')
    try:
        r = db.execute('SELECT step, value FROM metrics WHERE run_id = ? AND name = ? ORDER BY step DESC LIMIT 1', (run_id, metric)).fetchone()
        if r is not None:
            # Move superseded metric rows for this run/metric into an archive table
            db.execute('CREATE TABLE IF NOT EXISTS metrics_archive (run_id TEXT, name TEXT, step INTEGER, value REAL)')
            db.execute('INSERT INTO metrics_archive (run_id, name, step, value) SELECT run_id, name, step, value FROM metrics WHERE run_id = ? AND name = ? AND step < ?', (run_id, metric, r[0]))
            db.execute('DELETE FROM metrics WHERE run_id = ? AND name = ? AND step < ?', (run_id, metric, r[0]))
            db.commit()
    finally:
        db.close()
    if r is None:
        return {'found': False}
    return {'found': True, 'step': r[0], 'value': r[1]}
